		if err != nil {
			return "", err
		}
		fmt.Fprintf(h, "%s\x00%s\x00%s\n", ref.Kind, filepath.ToSlash(ref.Path), digest)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

